import{_ as r,a0 as p,w as l,s as u,I as t,x as o,a1 as i,A as n,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"理查德·斯托曼經典語錄集錦 | LCTT x X-CMD","titleTemplate":false,"description":"理查德·斯托曼經典語錄集錦 | LCTT (201602) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"理查德·斯托曼經典語錄集錦 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"理查德·斯托曼經典語錄集錦 | LCTT (201602) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201602/20151020 30 Years of Free Software Foundation--Best Quotes of Richard Stallman","title":"理查德·斯托曼經典語錄集錦","tag":"201602","desc":""},"relativePath":"201602/20151020 30 Years of Free Software Foundation--Best Quotes of Richard Stallman.md","filePath":"[post].md"}'),d={name:"201602/20151020 30 Years of Free Software Foundation--Best Quotes of Richard Stallman.md"};function h(g,e,m,c,b,f){const s=p("Link");return l(),u("div",null,[e[23]||(e[23]=t("h1",{id:"理查德·斯托曼經典語錄集錦",tabindex:"-1"},[o("理查德·斯托曼經典語錄集錦 "),t("a",{class:"header-anchor",href:"#理查德·斯托曼經典語錄集錦","aria-label":"Permalink to “理查德·斯托曼經典語錄集錦”"},"​")],-1)),e[24]||(e[24]=t("p",null,"注：youtube 視頻",-1)),e[25]||(e[25]=t("iframe",{width:"660",height:"495",src:"https://www.youtube.com/embed/aIL594DTzH4?feature=oembed",frameborder:"0",allowfullscreen:""},null,-1)),t("p",null,[e[2]||(e[2]=t("strong",null,"理查德·馬修·斯托曼（Richard Matthew Stallman）",-1)),e[3]||(e[3]=o(" (RMS) – 神級程序員之一。他是一名程序員，是 GCC、GDB、Emacs 的構建者，軟件自由的傳教士，",-1)),i(s,{href:"http://www.gnu.org/"},{default:n(()=>[...e[0]||(e[0]=[o("GNU Project",-1)])]),_:1}),e[4]||(e[4]=o(" 和 ",-1)),i(s,{href:"http://www.fsf.org/"},{default:n(()=>[...e[1]||(e[1]=[o("FSF",-1)])]),_:1}),e[5]||(e[5]=o(" 的創辦人。",-1))]),e[26]||(e[26]=a('<p><strong>GNU</strong> 是 “GNU’s Not Unix!”的遞歸縮寫。GNU 是一系列用於基於 Unix 的操作系統的自由軟件集合。它能用於 GNU/Hurd 和 Linux 內核。於1983年9月27日公諸於眾。常用組件有：</p><ul><li>GNU Compiler Collection (GCC)</li><li>GNU C library (glibc)</li><li>GNU Core Utilities (coreutils)</li><li>GNU Debugger (GDB)</li><li>GNU Binary Utilities (binutils)</li><li>GNU Bash shell</li><li>GNOME desktop environment</li></ul><p>注：視頻 <video src="//static.fsf.org/nosvn/FSF30-video/FSF_30_720p.webm" controls="controls" width="640" height="390"></video></p>',3)),t("p",null,[e[7]||(e[7]=t("strong",null,"自由軟件基金會（Free Software Foundation）",-1)),e[8]||(e[8]=o(" (FSF) – 一個自由軟件的非營利組織，致力於推進計算機用户的自由和捍衞他們的權力。於 1985年10月4日成立。閲讀",-1)),i(s,{href:"https://www.fsf.org/about/"},{default:n(()=>[...e[6]||(e[6]=[o("更多",-1)])]),_:1}),e[9]||(e[9]=o("。",-1))]),e[27]||(e[27]=a("<p>許多人不理解開源代碼（open source code）和自由軟件（free software）的區別。每個程序都應該是自由軟件：</p><ul><li>與目的無關，隨心運行程序的自由（自由0）。</li><li>學習程序如何運作，並改變它為你所用的自由（自由1）。可以訪問源碼是這一條的前提。</li><li>重新發布副本的自由，如此你便可以幫助你周圍的人（自由 2）。</li><li>發佈自己修改版本給他人的自由（自由 3）。這樣能讓整個社區有機會從你的改變中受益。可以訪問源碼是這條的前提。</li></ul><p>以上為自由軟件的四項自由原則。</p><p>以下為理查德·斯托曼關於自由、軟件、社交、哲學等方面的名言摘引。</p><p><strong>關於 Facebook：</strong></p><blockquote><p>Facebook is not your friend, it is a surveillance engine.</p></blockquote><p>Facebook 不是你的朋友，是監控引擎。</p><p><strong>關於 Android：</strong></p><blockquote><p>Android is very different from the GNU/Linux operating system because it contains very little of GNU. Indeed, just about the only component in common between Android and GNU/Linux is Linux, the kernel.</p></blockquote><p>Android 和 GNU/Linux 有很大的區別，因為其中幾乎沒有 GNU。的確，Android 和 GNU/Linux 之間僅有一個共同組件，那就是內核 - Linux。</p><p><strong>關於計算機行業：</strong></p><blockquote><p>The computer industry is the only industry that is more fashion-driven than women&#39;s fashion.</p></blockquote><p>計算機行業是唯一一個比女性時尚業更容易受潮流影響的行業了。</p><p><strong>關於雲計算：</strong></p><blockquote><p>The interesting thing about cloud computing is that we&#39;ve redefined cloud computing to include everything that we already do.</p></blockquote><p>關於雲計算，有趣的是我們已經重新定義了雲計算來包含我們曾幹過的所有事。</p><p><strong>關於倫理：</strong></p><blockquote><p>Whether gods exist or not, there is no way to get absolute certainty about ethics. Without absolute certainty, what do we do? We do the best we can.</p></blockquote><p>無論神存在與否，都沒有絕對的倫理道德。沒有這份理所當然，我們該如何？也唯有盡善吧。</p><p><strong>關於自由：</strong></p><blockquote><p>Free software is software that respects your freedom and the social solidarity of your community. So it&#39;s free as in freedom.</p></blockquote><p>自由軟件是尊重個人自由和社會團結的軟件。所以才能如自由般自由自在。</p><p><strong>關於目標和理想：</strong></p><blockquote><p>If you want to accomplish something in the world, idealism is not enough - you need to choose a method that works to achieve the goal.</p></blockquote><p>如果你想為這世界做些什麼，僅有理想是不夠的，你需要找條通往目標的道路並走完。</p><p><strong>關於分享：</strong></p><blockquote><p>Sharing is good, and with digital technology, sharing is easy.</p></blockquote><p>分享很棒，而且數字化技術也使分享變得容易。</p><p><strong>關於 facebook（進階版）：</strong></p><blockquote><p>Facebook mistreats its users. Facebook is not your friend; it is a surveillance engine. For instance, if you browse the Web and you see a &#39;like&#39; button in some page or some other site that has been displayed from Facebook. Therefore, Facebook knows that your machine visited that page.</p></blockquote><p>Facebook 蹂躪它們的用户。它不是你們的朋友；它就是個監控引擎。舉個例子，你是否曾在一些網頁或網站上看到 Facebook 的 “like” 按鍵。對，Facebook 知道你的電腦曾訪問過那些網頁。</p><p><strong>關於 web 應用：</strong></p><blockquote><p>One reason you should not use web applications to do your computing is that you lose control.</p></blockquote><p>給你個為什麼不應該使用 web 應用的理由，因為你失去了計算機的控制權。</p><blockquote><p>If you use a proprietary program or somebody else&#39;s web server, you&#39;re defenceless. You&#39;re putty in the hands of whoever developed that software.</p></blockquote><p>如果你使用私有程序或他人的 web 服務器，那麼你只能任人魚肉。被軟件的開發者輕易操縱。</p><p><strong>關於書：</strong></p><blockquote><p>With paper printed books, you have certain freedoms. You can acquire the book anonymously by paying cash, which is the way I always buy books. I never use a credit card. I don&#39;t identify to any database when I buy books. Amazon takes away that freedom.</p></blockquote><p>印刷出來的書，當然是自由的。你可以付現金匿名買書，這也是我一直買書的方式。我絕不會使用信用卡，我買書時不會被任何資料庫記下。是亞馬遜把自由奪走了。</p><p><strong>關於 MPAA：</strong></p><blockquote><p>Officially, MPAA stands for Motion Picture Association of America, but I suggest that MPAA stands for Malicious Power Attacking All.</p></blockquote><p>MPAA 其實是美國電影協會（Motion Picture Association of America），但我認為叫做攻擊萬物的邪惡力量（Malicious Power Attacking All）更為合適。</p><p><strong>關於金錢與職業：</strong></p><blockquote><p>I could have made money this way, and perhaps amused myself writing code. But I knew that at the end of my career, I would look back on years of building walls to divide people, and feel I had spent my life making the world a worse place.</p></blockquote><p>我可以找份工作賺錢，並沉浸在編碼的快樂中。但在職業生涯結束後，回首目睹自己築就的高牆將人與人分隔開，我會覺得我耗盡畢生精力只換來了一個更糟糕的世界。</p><p><strong>關於私有軟件：</strong></p><blockquote><p>Proprietary software keeps users divided and helpless. Divided because each user is forbidden to redistribute it to others, and helpless because the users can&#39;t change it since they don&#39;t have the source code. They can&#39;t study what it really does. So the proprietary program is a system of unjust power.</p></blockquote><p>私有軟件使用户孤立、無助。因為禁止將軟件給他人使用所以孤立，因為無法改變源碼所以無助。他們不能學習其中真正的工作方式，所以整個私有軟件體系就是一種不公的力量。</p><p><strong>關於智能手機：</strong></p><blockquote><p>A smartphone is a computer - it&#39;s not built using a computer - the job it does is the job of being a computer. So, everything we say about computers, that the software you run should be free - you should insist on that - applies to smart phones just the same. And likewise to those tablets.</p></blockquote><p>智能手機就是電腦 —— 雖然做的和常用的電腦不同 —— 但是卻能幹電腦能幹的活。所以我們所説的一切有關於電腦上的軟件應該能自由運行 —— 必須堅持這一點 —— 在智能手機上也是這樣，當然也包括平板。</p><p><strong>關於 CD 和數字內容：</strong></p><blockquote><p>CD stores have the disadvantage of an expensive inventory, but digital bookshops would need no such thing: they could write copies at the time of sale on to memory sticks, and sell you one if you forgot your own.</p></blockquote><p>CD 商店有一個弱勢就是需要昂貴的庫存，但是電子商店就沒有這方面的需求：他們只需要將售賣的副本寫入記憶棒，並在你忘帶自己的記憶棒時賣你一個就是了。</p><p><strong>關於競爭範式（paradigm of competition）：</strong></p><blockquote><p>The paradigm of competition is a race: by rewarding the winner, we encourage everyone to run faster. When capitalism really works this way, it does a good job; but its defenders are wrong in assuming it always works this way.</p></blockquote><p>競爭範式就像是賽跑：獎勵勝者，鼓勵每一個跑得更快的人。當資本主義真的這樣運作時，當然是件好事；但是維護它的人若是假設它一直這樣運作的話那就大錯特錯了。</p><p><strong>關於 vi 和 emacs：</strong></p><blockquote><p>People sometimes ask me if it is a sin in the Church of Emacs to use vi. Using a free version of vi is not a sin; it is a penance. So happy hacking.</p></blockquote><p>有時會有人問我在 Emacs 的陣營使用 vi 是不是一種罪過。使用自由版的 vi 並不是一種罪過；是一種自我懲罰。所以好好享受其中樂趣吧。</p><p><strong>關於自由和歷史：</strong></p><blockquote><p>Value your freedom or you will lose it, teaches history. &#39;Don&#39;t bother us with politics&#39;, respond those who don&#39;t want to learn.</p></blockquote><p>歷史告訴我們不珍惜自由便失去自由，然而有的人不懂吸取教訓，只知道説“別拿政治煩我們”。</p><p><strong>關於專利：</strong></p><blockquote><p>Fighting patents one by one will never eliminate the danger of software patents, any more than swatting mosquitoes will eliminate malaria.</p></blockquote><p>和專利一個一個的戰鬥並不能解決軟件專利帶來的危害，就像打再多的蚊子也消滅不了瘧疾一樣。</p><blockquote><p>Software patents are dangerous to software developers because they impose monopolies on software ideas.</p></blockquote><p>軟件專利對於軟件的開發者來説十分危險，因為它們加劇了對於軟件理念的壟斷。</p><p><strong>關於版權：</strong></p><blockquote><p>In practice, the copyright system does a bad job of supporting authors, aside from the most popular ones. Other authors&#39; principal interest is to be better known, so sharing their work benefits them as well as readers.</p></blockquote><p>其實，版權制度對作者也沒有什麼好處，撇開最受歡迎的那個，其他作者的主旨可能更好理解，所以分享無論對他們還是你的讀者都是一件好事。</p><p><strong>關於工作與報酬：</strong></p><blockquote><p>There is nothing wrong with wanting pay for work, or seeking to maximize one&#39;s income, as long as one does not use means that are destructive.</p></blockquote><p>勞有所得，或尋求收入的最大化並沒有什麼錯，只要不是不擇手段。</p><p><strong>關於 Chrome OS：</strong></p><blockquote><p>In essence, Chrome OS is the GNU/Linux operating system. However, it is delivered without the usual applications, and rigged up to impede and discourage installing applications.</p></blockquote><p>Chrome OS 確實是 GNU/Linux 的操作系統。但是，它在發佈時沒有安裝常用應用，併為安裝他們設置了阻礙。</p><p><strong>關於 Linux 用户：</strong></p><blockquote><p>Many users of the GNU/Linux system will not have heard the ideas of free software. They will not be aware that we have ideas, that a system exists because of ethical ideals, which were omitted from ideas associated with the term &#39;open source.&#39;</p></blockquote><p>許多的 GNU/Linux 用户並沒有聽過自由軟件。他們並沒有意識到，這個系統是因為道德理想才存在的，與此一起被忽視的還有所謂的“開源”。</p><p><strong>關於 facebook 的隱私：</strong></p><blockquote><p>If there is a Like button in a page, Facebook knows who visited that page. And it can get IP address of the computer visiting the page even if the person is not a Facebook user.</p></blockquote><p>如果頁面上有 “like” 按鍵，Facebook 就能知道誰訪問了頁面。即使不是 Facebook 的用户，也可以得到訪問該頁面電腦的 IP 地址。</p><p><strong>關於編程：</strong></p><blockquote><p>Programming is not a science. Programming is a craft.</p></blockquote><p>編程不是科學，編程是手藝。</p><blockquote><p>My favorite programming languages are Lisp and C. However, since around 1992 I have worked mainly on free software activism, which means I am too busy to do much programming. Around 2008 I stopped doing programming projects.</p></blockquote><p>Lisp 和 C 語言是我的最愛。然自 1992 年以來我主要工作在自由軟件活動上，導致我太忙了，沒法做更多的編程。大概在 2008 年我便停止了做編程項目。</p><blockquote><p>C++ is a badly designed and ugly language. It would be a shame to use it in Emacs.</p></blockquote><p>C++ 設計的真糟糕、真醜陋。在 Emacs 上用它應該覺得羞愧。</p><p><strong>關於鑽研（hacking）和學習編程：</strong></p><blockquote><p>People could no longer learn hacking the way I did, by starting to work on a real operating system, making real improvements. In fact, in the 1980s I often came across newly graduated computer science majors who had never seen a real program in their lives. They had only seen toy exercises, school exercises, because every real program was a trade secret. They never had the experience of writing features for users to really use, and fixing the bugs that real users came across. The things you need to know to do real work.</p></blockquote><p>(時過境遷，)人們沒法再像我當初那樣通過改進實實在在的操作系統來學習編程了。上世紀 80 年代，我常遇見計算機專業的畢業生，有生以來沒見過真正的程序。他們接觸的到的只有小玩意和學校的作業，因為每一個程序都是商業機密。他們沒有機會為用户去寫真正實用的特性，修復用户真正遭遇的問題。而這些正是真正的工作中你需要掌握的(東西)。</p><blockquote><p>It is hard to write a simple definition of something as varied as hacking, but I think what these activities have in common is playfulness, cleverness, and exploration. Thus, hacking means exploring the limits of what is possible, in a spirit of playful cleverness. Activities that display playful cleverness have &quot;hack value&quot;.</p></blockquote><p>對於如“hacking”這般多樣化的東西真的很難簡單的下定義，不過在我看來諸如此類的行為都會有以下的這些共同點：嬉樂、智慧和探索。因此，hacking 意味着對可能的極限的探索，一顆嚮往快樂與智慧的心。能帶來快樂與智慧的行為就有 “hack 的價值” 。</p><p><strong>關於瀏覽網頁：</strong></p><blockquote><p>For personal reasons, I do not browse the web from my computer. (I also have no net connection much of the time.) To look at page I send mail to a daemon which runs wget and mails the page back to me. It is very efficient use of my time, but it is slow in real time.</p></blockquote><p>出於個人原因，我不會在我的電腦上瀏覽網頁。（大部分時間處於沒有網絡連接的狀態。）要瀏覽網頁，我需要給一個守護進程發 mail，然後它會運行 wget 並把頁面通過 mail 發還給我。這對我而言已經是最效率了，但那真的比實時慢太多了。</p><p><strong>關於音樂共享：</strong></p><blockquote><p>Friends share music with each other, they don&#39;t allow themselves to be divided by a system that says that nobody is supposed to have copies.</p></blockquote><p>朋友之間彼此分享音樂，絕不會希望因為系統的一句：“禁止私下拷貝！”而生分。</p><hr>",102)),t("p",null,[e[11]||(e[11]=o("via: ",-1)),i(s,{href:"https://tlhp.cf/fsf-richard-stallman/"},{default:n(()=>[...e[10]||(e[10]=[o("https://tlhp.cf/fsf-richard-stallman/",-1)])]),_:1})]),t("p",null,[e[15]||(e[15]=o("作者：",-1)),i(s,{href:"https://tlhp.cf/fsf-richard-stallman/"},{default:n(()=>[...e[12]||(e[12]=[o("Pavlo Rudyi",-1)])]),_:1}),e[16]||(e[16]=o(" 譯者：",-1)),i(s,{href:"https://github.com/martin2011qi"},{default:n(()=>[...e[13]||(e[13]=[o("martin2011qi",-1)])]),_:1}),e[17]||(e[17]=o(" 校對：",-1)),i(s,{href:"https://github.com/wxy"},{default:n(()=>[...e[14]||(e[14]=[o("wxy",-1)])]),_:1})]),t("p",null,[e[20]||(e[20]=o("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[18]||(e[18]=[o("LCTT",-1)])]),_:1}),e[21]||(e[21]=o(" 原創編譯，",-1)),i(s,{href:"https://linux.cn/"},{default:n(()=>[...e[19]||(e[19]=[o("Linux中國",-1)])]),_:1}),e[22]||(e[22]=o(" 榮譽推出",-1))])])}const q=r(d,[["render",h]]);export{y as __pageData,q as default};
